#include <iostream>
#include <string>

int main() {
    std::string text = "The values in any left subtree\nare less than root";

    // Erase newline and following text starting at index 30
    text.erase(30);
    std::cout << "After erase:\n" << text << "\n\n";

    // Replace all spaces with a period
    std::size_t pos = text.find(' ');
    while (pos != std::string::npos) {
        text.replace(pos, 1, ".");
        pos = text.find(' ', pos + 1);
    }
    std::cout << "After replacing spaces:\n" << text << "\n\n";

    // Replace first period with a substring from source "xx::yy"
    pos = text.find('.');
    if (pos != std::string::npos) {
        // replace 1 char at pos with 2 chars from "xx::yy" starting at index 2
        text.replace(pos, 1, "xx::yy", 2, 2);
    }
    std::cout << "After replacing period with :: :\n" << text << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string s1 = "beginning end";
    std::string s2 = "middle ";

    // Insert s2 before index 10 in s1
    s1.insert(10, s2);
    std::cout << "After insert: " << s1 << "\n";

    std::string s3 = "12345678";
    std::string s4 = "xx";
    // Insert s4 at position 3 using subrange (from 0, entire string)
    s3.insert(3, s4, 0, std::string::npos);
    std::cout << "s3 after insert: " << s3 << "\n";

    // Convert to C-style string using c_str()
    const char* cStr = s1.c_str();
    std::cout << "c_str output: " << cStr << "\n";

    // Copy into a char buffer with copy()
    std::size_t len = s1.size();
    std::vector<char> buffer(len + 1); // safe modern buffer
    s1.copy(buffer.data(), len, 0);
    buffer[len] = '\0'; // null-terminator is required!
    std::cout << "buffer via copy(): " << buffer.data() << "\n";

    return 0;
}
